#!/usr/bin/env python3
"""Provenance verifier: resolve dir-qualified corpus ids, check quote exactness, print windows."""
import re, sys, json
from pathlib import Path

ROOT = Path("/home/user/BookMinder")
DIRS = {"v2": ROOT / ".coordination/mining/v2", "p": ROOT / ".coordination/mining/pairing"}
DIARY = ROOT / "claude-dev-log-diary"
ID_LINE = re.compile(r'^\s*-\s+(?:rule_id|gem_id|id):\s*"?([A-Za-z0-9_-]+)"?\s*$')
LOC_REF = re.compile(r"(day-\d{3})[a-z0-9-]*:L(\d+)(?:\s*[-–]\s*L?(\d+))?")

_index = {}
for tag, d in DIRS.items():
    for f in sorted(d.glob("*.yaml")):
        lines = f.read_text(errors="replace").splitlines()
        starts = [(i, m.group(1)) for i, line in enumerate(lines) if (m := ID_LINE.match(line))]
        for pos, (i, iid) in enumerate(starts):
            end = starts[pos + 1][0] if pos + 1 < len(starts) else len(lines)
            while end > i and not lines[end - 1].strip():
                end -= 1
            _index[(tag, iid)] = (f, i + 1, lines[i:end])


def norm(s):
    return re.sub(r"\s+", " ", s).strip().lower().replace("’", "'").replace("‘", "'").replace("“", '"').replace("”", '"')


def diary(day):
    p = DIARY / f"{day}.md"
    return p.read_text(errors="replace").splitlines() if p.exists() else None


def check_quotes(block, key):
    """For each quote-ish field, test whether it appears near cited loc."""
    txt = "\n".join(block)
    out = []
    # collect quote fields
    qs = re.findall(r'^\s*(quote|evidence|loc):\s*(.*)$', txt, re.M)
    quote_vals = [v for k, v in qs if k == "quote"]
    locs = [v for k, v in qs if k in ("evidence", "loc")]
    loclist = []
    for lv in locs:
        for m in LOC_REF.finditer(lv):
            loclist.append((m.group(1), int(m.group(2)), int(m.group(3) or m.group(2))))
    for qv in quote_vals:
        q = qv.strip()
        if q.startswith("'") and q.endswith("'"):
            q = q[1:-1].replace("''", "'")
        elif q.startswith('"') and q.endswith('"'):
            q = q[1:-1].replace('\\"', '"')
        if not q:
            continue
        nq = norm(q)
        best = None
        for (day, s, e) in loclist:
            dl = diary(day)
            if not dl:
                continue
            for w in (0, 3, 10, 40):
                lo, hi = max(0, s - 1 - w), min(len(dl), e + w)
                hay = norm(" ".join(dl[lo:hi]))
                if nq in hay:
                    # find exact line
                    ln = None
                    for n in range(lo, hi):
                        if norm(dl[n]) and norm(dl[n]) in nq or nq.startswith(norm(dl[n])[:40]) and len(norm(dl[n])) > 20:
                            ln = n + 1
                            break
                    best = f"MATCH w={w} {day}:L{ln or s}"
                    break
            if best:
                break
        out.append((q[:110], best or "NO-MATCH"))
    return out, loclist


def show(key, ctx=25, quiet=False):
    tag, iid = key.split(":", 1)
    if (tag, iid) not in _index:
        print(f"### MISSING {key}")
        return
    f, ln, block = _index[(tag, iid)]
    print(f"@@@ {key}  ({f.relative_to(ROOT)}:{ln})")
    print("\n".join(block))
    qres, locs = check_quotes(block, key)
    for q, r in qres:
        print(f"  QCHECK[{r}] {q}")
    if quiet:
        return
    seen = set()
    for (day, s, e) in locs:
        if (day, s, e) in seen:
            continue
        seen.add((day, s, e))
        dl = diary(day)
        if not dl:
            print(f"  ## {day}.md NOT FOUND")
            continue
        lo, hi = max(0, s - 1 - ctx), min(len(dl), e + ctx)
        print(f"  ## {day}:L{lo+1}-L{hi} (cited L{s}{'-L'+str(e) if e!=s else ''})")
        for n in range(lo, hi):
            mk = ">" if s <= n + 1 <= e else " "
            print(f"{mk}{n+1}\t{dl[n]}")
        print()


if __name__ == "__main__":
    args = sys.argv[1:]
    ctx, quiet, keys = 25, False, []
    it = iter(args)
    for a in it:
        if a == "-c":
            ctx = int(next(it))
        elif a == "-q":
            quiet = True
        elif a == "--list":
            for (t, i) in sorted(_index):
                print(t, i)
            sys.exit()
        else:
            keys.append(a)
    for k in keys:
        show(k, ctx, quiet)

